// A fraction of the screen: 0 at its left or top edge, 1 at its right or bottom edge.
export type Share = number

// A point on the screen as fractions of its width and height.
export type Point = [Share, Share]

// The gesture an intent announces.
export interface Gesture {
  // What it is: tap, long_press, swipe, drag, type, press, look, app or build. A viewer draws kinds it does not
  // know as a caption.
  kind: string
  duration_ms: number
  // Where it lands, in order; empty for a gesture with no place on the screen.
  points: Point[]
}

// A gesture about to land. While anyone watches, the server waits lead_ms after sending it, so the pointer arrives
// first.
export interface AgentIntent {
  type: 'agent'
  id: string
  phase: 'intent'
  agent: Agent
  // False when the agent cursor is off: an agent is using the device, and nothing is drawn.
  pointer: boolean
  // The label of the element the gesture lands on, if it has one.
  label: string
  caption: string
  lead_ms: number
  // How long the pointer stays, resting where it last acted, after the agent's last event. 0: only while the
  // gesture is drawn.
  linger_ms: number
  gesture: Gesture
}

// The gesture an intent announced is over.
export interface AgentDone {
  type: 'agent'
  id: string
  phase: 'done'
  ok: boolean
}

// An agent is still at work on the device -- a tool call has started, is running, or has just ended -- with nothing
// new to draw. Sent when a call starts and ends, and every WORKING_EVERY_S while a long one, such as a build or a
// test run, goes on.
export interface AgentWorking {
  type: 'agent'
  id: string
  phase: 'working'
  agent: Agent
  // True while the call runs, when another of these follows within WORKING_EVERY_S; false once it has ended.
  ongoing: boolean
  linger_ms: number
}

// What an agent is about to do on the device, whether it worked, and that it is still working. A viewer draws the
// intent with its own pointer, and keeps it while the agent works.
export type AgentEvent = AgentIntent | AgentDone | AgentWorking

// One finger's touch. A down, its moves and its up are one gesture on the device.
export interface TouchInput {
  type: 'touch'
  phase: TouchPhase
  nx: Share
  ny: Share
}

// A scroll wheel's movement at a point.
export interface ScrollInput {
  type: 'scroll'
  nx: Share
  ny: Share
  // How far the content moves, in points; positive scrolls down. The server clamps it to scroll_max_pt either way.
  dy: number
}

export interface ButtonInput {
  type: 'button'
  name: PanelButton
}

export interface KeyInput {
  type: 'key'
  name: KeyName
}

// Text for the focused field. It is typed as key presses, or put on the device's pasteboard and pasted, as the
