export interface ScopeStatusStream {
  encoding: EncodingSetting
  fps: number
}

export interface ScopeStatusCursor {
  enabled: boolean
  lead_ms: number
}

// Whether a scope can have a simulator, why not, how its device stands, and what the viewer is offered. The HTTP
// status route answers with it.
export interface ScopeStatus {
  enabled: boolean
  // Why the scope cannot have a simulator now; null when it can.
  reason: string | null
  device: Device | null
  stream: ScopeStatusStream
  cursor: ScopeStatusCursor
  // The connector that drives devices for this scope; null when none is available.
  connector: string | null
  capabilities: Capability[]
  // Why a connector other than the one asked for is in use; null otherwise.
  fallback_reason: string | null
}

// A scope's status once its device is being brought up, with a one-shot ticket for its screen socket.
export interface Started extends ScopeStatus {
  ticket: string
}

// A device a scope could use, for a device picker: a simulator on this Mac, or a real device connected to it.
export interface DeviceChoice {
  udid: string
  name: string
  runtime: string
  // What simctl says of a simulator, such as Booted or Shutdown; Connected or Disconnected for a real device.
  state: string
  created: boolean
  // Whether it is a simulator or a real device. An older server does not send it: read it as simulator.
  kind: DeviceKind
  // How a real device reaches this Mac; null for a simulator.
  connection: Connection | null
  // What a person should know before picking it, such as Locked or Developer Mode off; null when nothing.
  detail: string | null
  // Whether it can be picked now; detail says why not. An older server does not send it: read it as true.
  usable: boolean
}

// How the device stands: sent on the screen socket after the stream starts, and whenever that changes.
export interface StatusEvent extends Device {
  type: 'status'
}

// The encoding the server chose from the client's hello. Binary frames in that encoding follow.
export interface StreamStart {
  type: 'stream'
  encoding: Encoding
}
